-- Rubricas (plano de contas gerencial HKTC) — carga do fin_rubricas.xlsx.
-- Dado da EMPRESA (compartilhado): sem user_id. Leitura p/ autenticados; escrita só service_role.
-- Hierarquia achatada: cada linha = rubrica-folha (codigo = Rcoude, 9 chars) + níveis 1/2/3 p/ rollup (DRE).
-- 222 rubricas únicas (6 linhas idênticas R02500103 deduplicadas -> 1).

CREATE TABLE IF NOT EXISTS public.fin_rubricas (
  id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  codigo        text NOT NULL UNIQUE,          -- Rcoude / Rcoude04 (folha)
  nome          text NOT NULL,                 -- Rcoude04_Name
  nivel1_codigo text NOT NULL,                 -- Rcoude01
  nivel1_nome   text NOT NULL,
  nivel2_codigo text NOT NULL,                 -- Rcoude02
  nivel2_nome   text NOT NULL,
  nivel3_codigo text NOT NULL,                 -- Rcoude03
  nivel3_nome   text NOT NULL,
  ativa         boolean NOT NULL DEFAULT true,
  created_at    timestamptz NOT NULL DEFAULT now(),
  updated_at    timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE public.fin_rubricas ENABLE ROW LEVEL SECURITY;

CREATE INDEX IF NOT EXISTS fin_rubricas_n1_idx ON public.fin_rubricas (nivel1_codigo);
CREATE INDEX IF NOT EXISTS fin_rubricas_n2_idx ON public.fin_rubricas (nivel2_codigo);
CREATE INDEX IF NOT EXISTS fin_rubricas_n3_idx ON public.fin_rubricas (nivel3_codigo);

-- RLS: todo mundo do time lê; só service_role/import escreve.
DROP POLICY IF EXISTS fin_rubricas_select ON public.fin_rubricas;
CREATE POLICY fin_rubricas_select ON public.fin_rubricas FOR SELECT TO authenticated USING (true);
DROP POLICY IF EXISTS fin_rubricas_service_all ON public.fin_rubricas;
CREATE POLICY fin_rubricas_service_all ON public.fin_rubricas FOR ALL USING (auth.role() = 'service_role');

-- updated_at
CREATE OR REPLACE FUNCTION public.touch_updated_at()
RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$
BEGIN NEW.updated_at = now(); RETURN NEW; END; $$;
DROP TRIGGER IF EXISTS fin_rubricas_touch ON public.fin_rubricas;
CREATE TRIGGER fin_rubricas_touch BEFORE UPDATE ON public.fin_rubricas
  FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at();

-- ---------------- CARGA (idempotente) ----------------
ON CONFLICT (codigo) DO UPDATE SET
  nome = EXCLUDED.nome,
  nivel1_codigo = EXCLUDED.nivel1_codigo, nivel1_nome = EXCLUDED.nivel1_nome,
  nivel2_codigo = EXCLUDED.nivel2_codigo, nivel2_nome = EXCLUDED.nivel2_nome,
  nivel3_codigo = EXCLUDED.nivel3_codigo, nivel3_nome = EXCLUDED.nivel3_nome,
  updated_at = now();
